from pathlib import Path
from datetime import date
import csv, subprocess, re, sys

ref = date(2025,8,12)
periods = {
    'today': (ref, ref),
    'last_7_days': (date(2025,8,6), ref),
    'last_30_days': (date(2025,7,14), ref),
    'month_to_date': (date(2025,8,1), ref),
    'total': (date.min, date.max),
}
sevs = ['ERROR','WARNING','INFO']
pat = re.compile(r'^(\d{4}-\d{2}-\d{2})_[^.]+\.log$')
base = Path('/app/logs')
ind = {p:{s:0 for s in sevs} for p in periods}

for path in sorted(base.glob('*.log')):
    m = pat.match(path.name)
    if not m:
        continue
    fd = date.fromisoformat(m.group(1))
    for sev in sevs:
        c = int(subprocess.check_output(['grep','-c',f'\\[{sev}\\]', str(path)], text=True).strip())
        ind['total'][sev] += c
        for period, (start,end) in periods.items():
            if period == 'total':
                continue
            if start <= fd <= end:
                ind[period][sev] += c

csv_rows = []
with open('/app/summary.csv', newline='', encoding='utf-8') as f:
    for row in csv.DictReader(f):
        csv_rows.append(row)

csv_counts = {p:{s:None for s in sevs} for p in periods}
for row in csv_rows:
    csv_counts[row['period']][row['severity']] = int(row['count'])

print('INDEPENDENT_RECOUNT')
for p in ['today','last_7_days','last_30_days','month_to_date','total']:
    print(p, ind[p])
print('CSV_COUNTS')
for p in ['today','last_7_days','last_30_days','month_to_date','total']:
    print(p, csv_counts[p])
print('MATCH', ind == csv_counts)
if ind != csv_counts:
    for p in periods:
        for s in sevs:
            if ind[p][s] != csv_counts[p][s]:
                print('DIFF', p, s, ind[p][s], csv_counts[p][s])
                sys.exit(1)
